const { customer, status, paymentIntent, subscription, customerEmail, limit, startingAfter, expand } = $.input;

const params = {};
if (customer) params.customer = customer;
if (status) params.status = status;
if (paymentIntent) params.payment_intent = paymentIntent;
if (subscription) params.subscription = subscription;
if (customerEmail) params['customer_details[email]'] = customerEmail;
if (limit) params.limit = String(Math.max(1, Math.min(100, limit)));
if (startingAfter) params.starting_after = startingAfter;

if (expand && expand.length > 0) {
  expand.forEach((field, i) => {
    params[`expand[${i}]`] = field;
  });
}

return { params };

const resp = $.steps.listSessions.response || {};
const sessions = resp.data || [];

const sessionKeysToRemove = [
  'object', 'adaptive_pricing', 'after_expiration', 'branding_settings',
  'client_secret', 'collected_information', 'consent', 'consent_collection',
  'currency_conversion', 'custom_fields', 'custom_text', 'customer_creation',
  'customer_details', 'discounts', 'excluded_payment_method_types',
  'invoice_creation', 'livemode', 'locale', 'name_collection',
  'optional_items', 'origin_context', 'payment_method_configuration_details',
  'payment_method_options', 'permissions', 'presentment_details',
  'recovered_from', 'redirect_on_completion', 'return_url',
  'saved_payment_method_options', 'shipping_address_collection',
  'shipping_cost', 'shipping_details', 'shipping_options', 'submit_type',
  'tax_id_collection', 'total_details', 'ui_mode', 'wallet_options'
];

const lineItemKeysToRemove = ['object', 'amount_discount', 'amount_tax', 'discounts', 'price', 'taxes'];

function compress(session) {
  const s = { ...session };
  sessionKeysToRemove.forEach(k => delete s[k]);

  if (s.line_items && s.line_items.data) {
    delete s.line_items.has_more;
    delete s.line_items.url;
    s.line_items.data = s.line_items.data.map(item => {
      const li = { ...item };
      lineItemKeysToRemove.forEach(k => delete li[k]);
      return li;
    });
  }

  if (s.automatic_tax) {
    delete s.automatic_tax.liability;
    delete s.automatic_tax.provider;
  }

  return s;
}

const compressed = sessions.map(compress);

return {
  sessions: compressed,
  totalReturned: compressed.length,
  hasMore: resp.has_more || false,
  summary: `Retrieved ${compressed.length} checkout session${compressed.length === 1 ? '' : 's'}`
};
